from fastapi import Depends, FastAPI, HTTPException

app = FastAPI()

MEMO_DATA = {150: {'id': 150, 'title': 'Sample memo A', 'owner': {'id': 15}},
 151: {'id': 151, 'title': 'Sample memo B', 'owner': {'id': 35}}}


def get_current_user():
